(function () {
      var pageName = 'airport-hotels';
      var backToTopBtn = document.getElementById('backToTopBtn');

      function normalizeDestination(card) {
        if (!card) return 'unknown';
        var title = card.querySelector('.airport-card__title');
        if (!title) return 'unknown';
        var text = (title.textContent || '').trim();
        var iata = text.split('·').pop();
        return (iata || text).trim().toUpperCase();
      }

      function normalizeHotelName(link) {
        var block = link.closest('.hotel-block');
        var hotel = block ? block.querySelector('.hotel-block__name') : null;
        if (hotel) return hotel.textContent.trim();
        return link.textContent.trim().replace(/\s+/g, ' ');
      }

      function trackCtaClick(link) {
        if (!window.plausible) return;
        var card = link.closest('.airport-card');
        var destination = normalizeDestination(card);
        var eventName = link.classList.contains('hotel-cta') ? 'AirportHotel-CTA-Click' : 'AirportHotel-List-Click';
        plausible(eventName, {
          props: {
            page: pageName,
            destination: destination,
            hotel: normalizeHotelName(link),
            label: link.textContent.trim()
          }
        });
      }

      document.querySelectorAll('.hotel-cta, .stay22-link').forEach(function (link) {
        link.addEventListener('click', function () {
          trackCtaClick(link);
        });
      });

      function initAirportPhotos() {}

      initAirportPhotos();

      function initAirportHeadLinks() {
        var officialLinks = {
          BUD: 'https://www.bud.hu/',
          WAW: 'https://www.lotnisko-chopina.pl/en/index.html',
          BTS: 'https://www.bts.aero/en/',
          VIE: 'https://www.viennaairport.com/en/',
          PRG: 'https://www.prg.aero/en',
          KRK: 'https://www.krakowairport.pl/en/',
          OTP: 'https://www.bucharestairports.ro/en',
          ATH: 'https://www.aia.gr/traveler/',
          LJU: 'https://www.lju-airport.si/en/'
        };
        var promoAirports = { BUD: true, BTS: true, VIE: true, PRG: true };

        document.querySelectorAll('.airport-card').forEach(function (card) {
          var destination = normalizeDestination(card);
          if (!officialLinks[destination]) return;
          var head = card.querySelector('.airport-card__head');
          if (!head || head.querySelector('.airport-card__head-links')) return;

          var wrap = document.createElement('div');
          wrap.className = 'airport-card__head-links';

          var official = document.createElement('a');
          official.className = 'airport-card__head-link';
          official.href = officialLinks[destination];
          official.target = '_blank';
          official.rel = 'noopener';
          official.textContent = 'האתר הרשמי של השדה';
          wrap.appendChild(official);

          if (promoAirports[destination]) {
            var promo = document.createElement('a');
            promo.className = 'airport-card__head-link';
            promo.href = 'car-rental-partners.html';
            promo.target = '_blank';
            promo.rel = 'noopener';
            promo.textContent = 'הטבת השכרת רכב MATAY6';
            wrap.appendChild(promo);
          }

          head.appendChild(wrap);
        });
      }

      function initShortcutSpy() {
        var shortcutMap = {};
        document.querySelectorAll('.airport-shortcut[href^="#"]').forEach(function (link) {
          var id = (link.getAttribute('href') || '').slice(1);
          if (!id) return;
          shortcutMap[id] = link;
        });

        var activeLink = null;
        function setActive(link) {
          if (activeLink === link) return;
          if (activeLink) {
            activeLink.classList.remove('is-active');
            activeLink.removeAttribute('aria-current');
          }
          activeLink = link || null;
          if (activeLink) {
            activeLink.classList.add('is-active');
            activeLink.setAttribute('aria-current', 'location');
          }
        }

        var observer = new IntersectionObserver(function (entries) {
          entries.forEach(function (entry) {
            if (!entry.isIntersecting) return;
            var id = entry.target.id;
            if (id && shortcutMap[id]) setActive(shortcutMap[id]);
          });
        }, { rootMargin: '-40% 0px -50% 0px', threshold: 0.01 });

        Object.keys(shortcutMap).forEach(function (id) {
          var section = document.getElementById(id);
          if (section) observer.observe(section);
        });
      }

      initAirportHeadLinks();
      initShortcutSpy();

      var navEl = document.getElementById('nav');
      if (navEl) {
        window.addEventListener(
          'scroll',
          function () {
            navEl.classList.toggle('scrolled', window.scrollY > 10);
          },
          { passive: true }
        );
      }

      if (!backToTopBtn) return;

      function toggleBackToTopButton() {
        if (window.scrollY > 360) {
          backToTopBtn.classList.add('is-visible');
          return;
        }
        backToTopBtn.classList.remove('is-visible');
      }

      backToTopBtn.addEventListener('click', function () {
        window.scrollTo({ top: 0, behavior: 'smooth' });
        if (window.plausible) {
          plausible('AirportHotels-BackToTop-Click', { props: { page: pageName } });
        }
      });

      window.addEventListener('scroll', toggleBackToTopButton, { passive: true });
      toggleBackToTopButton();
    })();
